//! Typed consumers: one handler trait + dispatcher per subscription,
//! plus the process-wide registry the webhook drain dispatches through.
//! Generated by codegraph. DO NOT EDIT.
//!
//! The application installs handlers at startup (`register_*`); the
//! drain calls [`dispatch_registered`] for every message it reads. Idempotency keying is generated:
//! every delivery is keyed on (pgmq msg_id, consumer) and handlers run on
//! first delivery only; they may still be non-transactional — a crash
//! after the dedupe insert but before side effects commits loses that
//! run's effects (the at-least-once floor).


use async_trait::async_trait;
use sea_orm::{ConnectionTrait, DatabaseBackend, DatabaseConnection, Statement};
use crate::events::contracts::{OrderPlacedPayload};


/// Context handed to `audit-worker` handlers: the drain's database
/// handle.
pub struct AuditWorkerContext<'a> {
    pub db: &'a DatabaseConnection,
}

/// Handler contract for the `audit-worker` consumer. The app
/// overrides the event methods it cares about; the defaults are no-ops.
#[async_trait]
pub trait AuditWorkerHandler: Send + Sync {
    async fn on_order_placed(
        &self,
        ctx: &AuditWorkerContext<'_>,
        event: &OrderPlacedPayload,
    ) -> anyhow::Result<()> {
        let _ = (ctx, event);
        Ok(())
    }
}

/// Dispatch one typed envelope to a `AuditWorkerHandler`.
/// `Ok(())` when the event is not subscribed or the handler succeeded;
/// `Err(reason)` when the payload is missing/unparseable or the handler
/// errors — the reason rides the DLQ metadata (#611).
pub async fn dispatch_audit_worker(
    handler: &dyn AuditWorkerHandler,
    ctx: &AuditWorkerContext<'_>,
    envelope: &serde_json::Value,
) -> Result<(), String> {
    let Some(event) = event_name_of(envelope) else {
        return Ok(());
    };
    match event {
        "OrderPlaced" => {
            let Some(payload) = payload_of(envelope) else {
                tracing::warn!(event = %event, consumer = "audit-worker", "typed envelope without a payload; skipped");
                return Err("typed envelope without a payload".to_string());
            };
            let Ok(payload) = serde_json::from_value::<OrderPlacedPayload>(payload.clone()) else {
                tracing::warn!(event = %event, consumer = "audit-worker", "payload failed to deserialize; skipped");
                return Err("payload failed to deserialize".to_string());
            };
            handler.on_order_placed(ctx, &payload).await.map_err(|e| {
                tracing::warn!(event = %event, consumer = "audit-worker", error = %e, "consumer handler failed");
                e.to_string()
            })
        }
        other => {
            tracing::debug!(event = %other, consumer = "audit-worker", "event not subscribed; skipped");
            Ok(())
        }
    }
}

/// Install the handler for the `audit-worker` consumer. Call once
/// at startup, before the webhook dispatcher starts draining.
pub fn register_audit_worker(
    handler: std::sync::Arc<dyn AuditWorkerHandler>,
) {
    let events: &'static [&'static str] = &["OrderPlaced"];
    let dispatch: DispatchFn = std::sync::Arc::new(move |db, envelope| {
        let handler = std::sync::Arc::clone(&handler);
        Box::pin(async move {
            let ctx = AuditWorkerContext { db: &db };
            dispatch_audit_worker(handler.as_ref(), &ctx, &envelope).await
        })
    });
    let mut guard = match registry().write() {
        Ok(guard) => guard,
        Err(poisoned) => poisoned.into_inner(),
    };
    guard.push(RegisteredConsumer {
        name: "audit-worker",
        events,
        dispatch,
    });
}

